export function iconImg(icon: IconRef | undefined, className = 'sav-icon'): HTMLElement | null {
  if (!icon) return null;
  return h('img', { class: className, src: icon.src, alt: '', title: icon.label, loading: 'lazy', decoding: 'async' });
}

export function goodsIcon(id: number): IconRef | undefined { return GOODS_ICONS[id]; }
export function professionIcon(id: number): IconRef | undefined { return PROFESSION_ICONS[id]; }
export function terrainIcon(id: number): IconRef | undefined { return TERRAIN_ICONS[id]; }

export function unitIcon(type: number, spec?: number): IconRef | undefined {
  if (type === 0 && spec !== undefined) return PROFESSION_ICONS[spec] ?? PROFESSION_ICONS[19];
  return UNIT_ICONS[type];
}

export function colonyFortLevel(colony: Record<string, unknown>): number {
  const flags = bytesFromB64(colony.flags2);
  let level = 0;
  for (let bit = 0; bit < 3; bit++) {
    const byte = flags[bit >> 3] ?? 0;
    if (byte & (1 << (bit & 7))) level++;
  }
  return Math.max(0, Math.min(3, level));
}

export function colonyIcon(colony: Record<string, unknown>): IconRef | undefined {
  const nation = Number(colony.nation);
  const nationIdx = Number.isFinite(nation) ? Math.max(0, Math.min(3, Math.trunc(nation))) : 1;
  return COLONY_ICONS[nationIdx]?.[colonyFortLevel(colony)] ?? COLONY_ICONS[1]?.[colonyFortLevel(colony)];
}

export function settlementIcon(
  settlement: Record<string, unknown>,
  tribes?: Array<Record<string, unknown>>,
): IconRef | undefined {
  const owner = Number(settlement.owner);
  const tribe = Number.isFinite(owner) ? tribes?.[Math.trunc(owner) - 4] : undefined;
  const level = Number(tribe?.level);
  if (Number.isFinite(level)) {
    const idx = Math.max(0, Math.min(3, Math.trunc(level)));
    return VILLAGE_ICONS[idx] ?? VILLAGE_ICONS[0];
  }

  const size = Number(settlement.size ?? 0);
  const fallback = Number.isFinite(size) ? Math.max(0, Math.min(3, Math.trunc(size))) : 0;
  return VILLAGE_ICONS[fallback] ?? VILLAGE_ICONS[0];
}

export function mapIconImage(icon: IconRef | undefined): HTMLImageElement | undefined {
  if (!icon) return undefined;
  let img = IMAGE_CACHE.get(icon.src);
  if (!img) {
    img = new Image();
    img.decoding = 'async';
    img.src = icon.src;
    IMAGE_CACHE.set(icon.src, img);
  }
  return img;
}

function bytesFromB64(value: unknown): Uint8Array {
  const b64 = typeof value === 'object' && value !== null && '$b64' in value
    ? String((value as { $b64: unknown }).$b64)
    : '';
  if (!b64) return new Uint8Array();
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

const IMAGE_CACHE = new Map<string, HTMLImageElement>();
